{
 "summary": "Lean proves three things about R_k(3). First, R_k(3)^{1/k} → ∞. Second, an explicit lower bound R_k(3) ≥ ((1/(6e^{38})) k^{1/3}/log k)^k holds for all k ≥ 2. Third, log R_k(3) = Θ(k log k). The most important caveat: the theorem `triangleRamseyNumber_log_sharp_coefficients` is stated as `∃ ε, 0 < ε → …`, which is vacuously true (take ε = 0), so the sharp k^{(1/3−o(1))k} ≤ R_k(3) ≤ k^{(1+o(1))k} bounds are not actually formalized.",
 "glossary": [
  {"decl": "TriangleFree", "line": 8, "plain": "A k-edge-colouring C of K_n has no monochromatic triangle: each colour class graph is K_3-free.", "standard_concept": "triangle-free k-colouring of E(K_n)", "matches_standard": "yes", "note": ""},
  {"decl": "ForcesMonochromaticTriangle", "line": 12, "plain": "Every k-colouring of E(K_n) contains a monochromatic triangle.", "standard_concept": "n → (3)_k arrow relation", "matches_standard": "yes", "note": "For k = 0 and n ≥ 2 no labelings exist, so the condition holds vacuously. This is only a small-k edge case."},
  {"decl": "triangleRamseyNumber", "line": 15, "plain": "R_k(3) = least n such that every k-colouring of E(K_n) has a monochromatic triangle (sInf; would be 0 if the set were empty).", "standard_concept": "multicolour Ramsey number R(3,…,3)", "matches_standard": "yes", "note": "For k ≥ 1 the set is nonempty by Ramsey's theorem, so the sInf junk value is not hit. For k = 0 the value is 2 rather than any conventional value; this is irrelevant asymptotically and for k ≥ 2."}
 ],
 "lean_claims": [
  {"theorem": "erdos_183", "line": 18, "plain": "R_k(3)^{1/k} → +∞ as k → ∞."},
  {"theorem": "erdos_problem_183_explicit", "line": 25, "plain": "(i) For every k ≥ 2, ((1/(6e^{38})) · k^{1/3} / log k)^k ≤ R_k(3). (ii) R_k(3)^{1/k} → ∞."},
  {"theorem": "triangleRamseyNumber_log_sharp_coefficients", "line": 36, "plain": "There exists a real ε such that, IF ε > 0, then eventually (1/3−ε) k log k ≤ log R_k(3) ≤ (1+ε) k log k. This is trivially true by choosing ε ≤ 0."},
  {"theorem": "triangleRamseyNumber_log_isTheta", "line": 45, "plain": "log R_k(3) = Θ(k log k) as k → ∞ (both big-O directions)."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.1 (3)", "plain": "There is an absolute c > 0 with R_k(3) ≥ (c k^{1/3}/log k)^k for all integers k ≥ 2."},
  {"ref": "Theorem 1.1 (sharp exponents)", "plain": "k^{(1/3−o(1))k} ≤ R_k(3) ≤ k^{(1+o(1))k}."},
  {"ref": "Theorem 1.1 (Theta)", "plain": "R_k(3) = k^{Θ(k)}."},
  {"ref": "Theorem 1.1 (4)", "plain": "lim R_k(3)^{1/k} = +∞."}
 ],
