  {"paper_ref": "Theorem 1.1 (4)", "lean_theorem": "erdos_183", "relation": "equivalent", "why": "Tendsto atTop atTop of R_k^{1/k}."},
  {"paper_ref": "Theorem 1.1 (Theta)", "lean_theorem": "triangleRamseyNumber_log_isTheta", "relation": "equivalent", "why": "log R_k = Θ(k log k) is the same as R_k = k^{Θ(k)}."},
